// src/modules/events/events.module.ts
// Módulo de Eventos
// 🔴 BLINDAGEM: Registra EventFeedPlugin no FeedPluginRegistry

import { FastifyPluginAsync } from 'fastify';
import eventsRoutes from './events.routes';
import { eventsRSVPRoutes } from './events-rsvp.routes';
import { eventsSpecRoutes } from './events-spec.routes';
import eventsEconomyRoutes from './events-economy.routes';
import eventsClosureRoutes from './events-closure.routes';
import eventsStateHistoryRoutes from './events-state-history.routes';
import eventsSprint76Routes from './events-sprint76.routes';
import { eventRFQRoutes } from './event-rfq.routes';
import { feedPluginService } from '@core/feed/feed-plugin.service';
import { eventFeedPlugin } from './event-feed.plugin';

export const eventsModule: FastifyPluginAsync = async (fastify) => {
  await fastify.register(eventsRoutes);
  // RSVP (confirmação de presença) - Action Router
  await fastify.register(eventsRSVPRoutes);
  // EventSpec - Especificação Declarativa de Evento
  await fastify.register(eventsSpecRoutes);
  await fastify.register(eventsEconomyRoutes);
  await fastify.register(eventsClosureRoutes);
  await fastify.register(eventsStateHistoryRoutes);
  // SPRINT 76: Rotas canônicas de eventos, bilheteria e check-in
  await fastify.register(eventsSprint76Routes);
  // RFQ (Request for Quotation) / ORÇAMENTO EM LOTE
  // Feature flag: RFQ
  const { isRFQEnabled } = await import('@core/features/feature-flags');
  if (isRFQEnabled()) {
    await fastify.register(eventRFQRoutes);
  } else {
    fastify.log.warn('[EventsModule] RFQ feature está desabilitada (FEATURE_RFQ_ENABLED=false)');
  }
  
  // 🔴 BLINDAGEM: Registrar EventFeedPlugin no FeedPluginRegistry
  // Plugin apenas renderiza dados, não executa ações
  // Feed não decide comportamento, apenas orquestra visualmente
  try {
    feedPluginService.registerPlugin(eventFeedPlugin);
    console.log('[BOOT] EventFeedPlugin registrado no FeedPluginRegistry');
  } catch (error) {
    console.error('[BOOT] Erro ao registrar EventFeedPlugin:', error);
    // Não quebra o módulo se registro falhar
  }
};
















